var DATA={
  '通用':[['Ctrl/⌘ + C','复制'],['Ctrl/⌘ + V','粘贴'],['Ctrl/⌘ + Z','撤销'],['Ctrl/⌘ + S','保存'],['Ctrl/⌘ + F','查找']],
  'VSCode':[['Ctrl/⌘ + P','快速打开文件'],['Ctrl/⌘ + `','切换终端'],['Shift + Alt + F','格式化文档'],['F12','跳转到定义'],['Ctrl/⌘ + B','切换侧边栏']],
  '浏览器':[['Ctrl/⌘ + T','新标签页'],['Ctrl/⌘ + L','聚焦地址栏'],['Ctrl/⌘ + W','关闭标签'],['Ctrl/⌘ + Shift + T','恢复关闭的标签'],['Ctrl/⌘ + D','收藏当前页']],
  '系统':[['Win/⌘ + D','显示桌面'],['Win/⌘ + E','打开文件管理器'],['Alt + Tab','切换窗口'],['Win/⌘ + Space','切换输入法']]
};
function shortcutsFor(app){
  if(!DATA[app]) app='通用';
  var d=DATA[app];
  return {app:app, items:d.map(function(x){ return {key:x[0], desc:x[1]}; })};
}
var EXPORTS={shortcutsFor:shortcutsFor};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KeyboardForgePure = EXPORTS; }
